   242→export default function StatusesScreen() {
   243→  const COLORS = useThemeColors();
   244→  const styles = useMemo(() => createStyles(COLORS), [COLORS]);
   245→  const [activeTab, setActiveTab] = useState<TabType>('images');
   246→  // Track which tabs have been visited at least once. Once a tab is opened,
   247→  // its FlashList stays mounted forever — switching back is instant with no
   248→  // re-decode of thumbnails. Only the very first paint is single-grid (the
   249→  // launch heat fix); after one swipe both grids stay alive.
   250→  const [visitedTabs, setVisitedTabs] = useState<Record<TabType, boolean>>({
   251→    images: true,
   252→    videos: false,
   253→  });
   254→  const [selectedSource, setSelectedSource] = useState<StatusSource>('whatsapp');
   255→  const saveRating = useMilestoneRating('save');
   256→  const shareRating = useMilestoneRating('share');
   257→  const {
   258→    statuses,
   259→    isLoading,
   260→    isRefreshing,
   261→    isInitializing,
   262→    isGrantingAccess,
   263→    hasPermission,
   264→    safGranted,
   265→    safUris,
   266→    isRequestingSAF,
   267→    androidVersion,
   268→    requestSAF,
   269→    loadStatuses,
   270→    refresh,
   271→    saveStatus,
   272→    shareStatus,
   273→  } = useMedia();
   274→
   275→  const insets = useSafeAreaInsets();
   276→
   277→  const scrollViewRef = useRef<ScrollView>(null);
   278→  const navigationRef = useRef<Map<string, number>>(new Map());
   279→  const lastRefreshTime = useRef<number>(0);
   280→  const activeTabRef = useRef<TabType>(activeTab);
   281→
   282→  // Consolidated Load Effect:
   283→  // Triggers on mount, or whenever permissions are granted.
   284→  useEffect(() => {
   285→    if (isGrantingAccess) return;
   286→    
   287→    const needsSAF = androidVersion >= 30;
   288→    const isReady = hasPermission || (needsSAF && safGranted);
   289→    
   290→    if (isReady) {
   291→      loadStatuses();
   292→    }
   293→  }, [hasPermission, safGranted, isGrantingAccess, androidVersion]);
   294→
   295→  // Keep a ref to refresh so the AppState listener is never torn down/re-added
   296→  // when refresh changes identity (happens whenever loadStatuses re-creates due to
   297→  // safUris/hasPermission changes). Re-adding mid-session causes brief listener gaps.
   298→  const refreshRef = useRef(refresh);
   299→  useEffect(() => { refreshRef.current = refresh; });
   300→
   301→  // Auto-refresh when the user returns to the app — but ONLY if it has been
   302→  // at least 30 minutes since the last refresh. Statuses don't change often
   303→  // enough to justify a full SAF folder walk every time the app blinks
   304→  // active. The user can always pull-to-refresh for an explicit refresh.
   305→  // The initial load on app open is handled by the mount effect above; this
   306→  // only catches "user came back after a long time".
   307→  // Also defers via InteractionManager so the refresh never races a tap/scroll.
   308→  const APP_STATE_REFRESH_THROTTLE_MS = 30 * 60 * 1000; // 30 minutes
   309→  useEffect(() => {
   310→    // Seed the timestamp so the very first AppState→active right after
   311→    // launch never re-triggers a refresh on top of the initial load.
   312→    lastRefreshTime.current = Date.now();
   313→    const sub = AppState.addEventListener('change', (state) => {
   314→      if (state === 'active') {
   315→        const now = Date.now();
   316→        if (now - lastRefreshTime.current > APP_STATE_REFRESH_THROTTLE_MS) {
   317→          lastRefreshTime.current = now;
   318→          InteractionManager.runAfterInteractions(() => {
   319→            refreshRef.current(true); // silent — no shimmer while watching
   320→          });
   321→        }
   322→      }
   323→    });
   324→    return () => sub.remove();
   325→  }, []); // stable — uses ref for refresh
   326→
   327→  const selectedSourceLabel = selectedSource === 'whatsapp_business' ? 'WhatsApp Business' : 'WhatsApp';
   328→  const selectedStatuses = useMemo(
   329→    () => statuses.filter(s => s.source === selectedSource),
   330→    [statuses, selectedSource]
   331→  );
   332→
   333→  const imageCnt = useMemo(() => selectedStatuses.filter(s => s.type === 'image').length, [selectedStatuses]);
   334→  const videoCnt = useMemo(() => selectedStatuses.filter(s => s.type === 'video').length, [selectedStatuses]);
   335→
   336→  const filteredImages = useMemo(
   337→    () => selectedStatuses.filter(s => s.type === 'image'),
   338→    [selectedStatuses]
   339→  );
   340→
   341→  const filteredVideos = useMemo(
   342→    () => selectedStatuses.filter(s => s.type === 'video'),
   343→    [selectedStatuses]
   344→  );
   345→
   346→  const handlePress = useCallback((item: StatusItem) => {
   347→    const now = Date.now();
   348→    const lastPress = navigationRef.current.get(item.id) || 0;
   349→    // Prevent double-tap navigation within 300ms
   350→    if (now - lastPress < 300) return;
   351→    navigationRef.current.set(item.id, now);
   352→
   353→    if (item.type === 'image') {
   354→      // For images: prefetch into expo-image's memory-disk cache so the
   355→      // viewer's <Image> resolves from cache instead of waiting for the
   356→      // ContentResolver decode (800 ms–2 s on Android 11+).
   357→      const uri = item.uri;
   358→      const t = Date.now();
   359→      if (
   360→        !prefetchedTapUris.has(uri) &&
   361→        t - lastPrefetchTime >= PREFETCH_THROTTLE_MS
   362→      ) {
   363→        prefetchedTapUris.add(uri);
   364→        lastPrefetchTime = t;
   365→        ExpoImage.prefetch(uri, 'memory-disk')
   366→          .catch(() => {})
   367→          .finally(() => {
   368→            setTimeout(() => prefetchedTapUris.delete(uri), 30000);
   369→          });
   370→      }
   371→    }
   372→
   373→    router.push({
   374→      pathname: '/viewer',
   375→      params: { id: item.id },
   376→    });
   377→  }, [prepareStatusForViewing]);
   378→
   379→  // PERF: Cast handlers to (item) => void for the MediaCard's stable-handler
   380→  // signature. handlePress is already an (item: StatusItem) => void closure
   381→  // memoised by useCallback above — passing it directly lets React.memo on
   382→  // MediaCard skip re-renders, so the in-flight touch event isn't dropped on
   383→  // Android 11. (Inline `() => handlePress(item)` was the root cause of
   384→  // "I have to tap 3-4 times to open the image".)
   385→  const handleSave = useCallback((item: StatusItem) => {
   386→    saveStatus(item);
   387→    saveRating.increment();
   388→  }, [saveStatus, saveRating.increment]);
   389→
   390→  const handleShare = useCallback((item: StatusItem) => {
   391→    shareStatus(item);
   392→    shareRating.increment();
   393→  }, [shareStatus, shareRating.increment]);
   394→
   395→  const handlePressAny = useCallback((item: any) => handlePress(item as StatusItem), [handlePress]);
   396→  const handleSaveAny = useCallback((item: any) => handleSave(item as StatusItem), [handleSave]);
   397→  const handleShareAny = useCallback((item: any) => handleShare(item as StatusItem), [handleShare]);
   398→
   399→  // Stable per-cell renderers. Defining these as arrow functions inline on
   400→  // the FlashList's `renderItem` prop creates a new function identity on
   401→  // every parent render, which forces FlashList to re-mount every visible
   402→  // cell — the dominant cause of "stuck while scrolling" on Android 11+.
   403→  // Pulling them up here behind useCallback keeps the identity stable so
   404→  // FlashList only re-renders the specific cells whose data actually
   405→  // changed (handled by React.memo on MediaCard).
   406→  const renderImageItem = useCallback(
   407→    ({ item }: { item: StatusItem }) => (
   408→      <MediaCard
   409→        item={item}
   410→        onPress={handlePressAny}
   411→        onSave={handleSaveAny}
   412→        onShare={handleShareAny}
   413→        showSaveButton
   414→      />
   415→    ),
   416→    [handlePressAny, handleSaveAny, handleShareAny],
   417→  );
   418→  const renderVideoItem = useCallback(
   419→    ({ item }: { item: StatusItem }) => (
   420→      <MediaCard
   421→        item={item}
   422→        onPress={handlePressAny}
   423→        onSave={handleSaveAny}
   424→        onShare={handleShareAny}
   425→        showSaveButton
   426→      />
   427→    ),
   428→    [handlePressAny, handleSaveAny, handleShareAny],
   429→  );
   430→
   431→  const overrideItemLayout = useCallback((layout: any) => {
   432→    layout.size = CARD_SIZE;
   433→    layout.span = 1;
   434→  }, []);
   435→
   436→  const getItemLayout = useCallback(
   437→    (_data: ArrayLike<StatusItem> | null | undefined, index: number) => ({
   438→      length: ROW_HEIGHT,
   439→      offset: ROW_HEIGHT * Math.floor(index / GRID_COLUMNS),
   440→      index,
   441→    }),
   442→    []
   443→  );
   444→
   445→  const selectedSafGranted = Platform.OS === 'android'
   446→    ? Boolean(safUris[selectedSource])
   447→    : true;
   448→
   449→  // ON ANDROID 11+ (API 30+): We require SAF (Folder Access) for reading statuses.
   450→  // ON ANDROID 10 & BELOW: We only require standard Media Library permission.
   451→  const showPermScreen = Platform.OS === 'android' && (
   452→    androidVersion >= 30 ? !selectedSafGranted : !hasPermission
   453→  );
   454→
   455→  const handleGrantAccess = useCallback(() => {
   456→    if (androidVersion >= 30) {
   457→      requestSAF(selectedSource);
   458→    } else {
   459→      // For legacy versions, send them to the permissions guide
   460→      router.push('/permissions');
   461→    }
   462→  }, [requestSAF, selectedSource, androidVersion]);
   463→
   464→  const markVisited = useCallback((tab: TabType) => {
   465→    setVisitedTabs(prev => (prev[tab] ? prev : { ...prev, [tab]: true }));
   466→  }, []);
   467→
   468→  // PRE-WARM the videos tab AFTER first paint of images settles.
   469→  // Without this, the videos FlashList only mounts when the user finishes
   470→  // swiping — causing a CPU spike right at the end of the swipe (jank)
   471→  // and a black flash because thumbnails haven't decoded yet.
   472→  // We wait for: (a) interactions to settle, (b) data is loaded, then
   473→  // (c) a small idle gap so first paint is buttery smooth, then silently
   474→  // mount the videos grid offscreen. By the time the user swipes there,
   475→  // it's fully rendered — instant, zero jank.
   476→  useEffect(() => {
   477→  if (visitedTabs.videos) return;
   478→  if (filteredVideos.length === 0) return;
   479→  if (isLoading || isInitializing) return;
   480→  
   481→  // Use requestIdleCallback if available (web + modern Android)
   482→  const idleCallback = (callback: IdleRequestCallback) => {
   483→    if ('requestIdleCallback' in global) {
   484→      return (global as any).requestIdleCallback(callback, { timeout: 2000 });
   485→    }
   486→    // Fallback: setTimeout with longer delay
   487→    return setTimeout(callback, 2000);
   488→  };
   489→  
   490→  const handle = InteractionManager.runAfterInteractions(() => {
   491→    idleCallback(() => {
   492→      // Only mount if still unvisited
   493→      setVisitedTabs(prev => (prev.videos ? prev : { ...prev, videos: true }));
   494→    });
   495→  });
   496→  
   497→  return () => {
   498→    if (typeof handle === 'number') {
   499→      clearTimeout(handle);
   500→    } else {
   501→      handle?.cancel?.();
   502→    }
   503→  };
   504→}, [filteredVideos.length, isLoading, isInitializing, visitedTabs.videos]);
   505→
   506→  // The instant the user STARTS dragging the horizontal pager, mount BOTH
   507→  // grids. This way the destination grid renders DURING the swipe
   508→  // animation rather than at the end — eliminating the jank spike and
   509→  // black flash users see today.
   510→  const onScrollBeginDrag = useCallback(() => {
   511→    setVisitedTabs(prev => {
   512→      if (prev.images && prev.videos) return prev;
   513→      return { images: true, videos: true };
   514→    });
   515→  }, []);
   516→
   517→  // Pull-to-refresh handler. We pass `silent=true` so the global isLoading
   518→  // flag doesn't flip — that flag would unmount the FlashList and blank the
   519→  // entire grid. The RefreshControl's own pull spinner already gives the
   520→  // user clear visual feedback that a refresh is in flight, so the screen
   521→  // can stay populated with existing thumbnails (Instagram-style "selective
   522→  // patching"): unchanged items stay mounted, new ones slide in, removed
   523→  // ones slide out — no flicker, no scroll-position loss.
   524→  const handlePullRefresh = useCallback(() => {
   525→    refresh(true);
   526→  }, [refresh]);
   527→
   528→  const handleTabChange = useCallback((tab: TabType) => {
   529→    setActiveTab(tab);
   530→    markVisited(tab);
   531→    if (scrollViewRef.current) {
   532→      scrollViewRef.current.scrollTo({
   533→        x: tab === 'images' ? 0 : SW,
   534→        animated: true,
   535→      });
   536→    }
   537→  }, [markVisited]);
   538→
