package expo.modules.exoplayer;

import android.content.Context;
import android.net.Uri;
import android.widget.FrameLayout;
import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.media3.common.MediaItem;
import androidx.media3.common.PlaybackException;
import androidx.media3.common.Player;
import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.ui.AspectRatioFrameLayout;
import androidx.media3.ui.PlayerView;
import com.facebook.react.bridge.Arguments;
import com.facebook.react.bridge.WritableMap;
import com.facebook.react.uimanager.ThemedReactContext;
import com.facebook.react.uimanager.events.RCTEventEmitter;

/**
 * ExoPlayerView — native Android video view backed by Media3 ExoPlayer.
 *
 * CONTRACT: only accepts file:// URIs. Passing a content:// URI will
 * emit an onPlayerError event immediately — ExoPlayer buffer-starves on
 * SAF URIs, so the JS layer must always copy to file:// first via
 * SafReaderModule.copyFileToCache before handing off here.
 */
public class ExoPlayerView extends FrameLayout {

    private final ThemedReactContext reactContext;
    private ExoPlayer player;
    private PlayerView playerView;

    private String currentFileUri = null;
    private boolean paused = false;
    private boolean muted = false;

    public ExoPlayerView(@NonNull ThemedReactContext context) {
        super(context);
        this.reactContext = context;
        setupPlayerView();
    }

    private void setupPlayerView() {
        playerView = new PlayerView(getContext());
        playerView.setUseController(false);
        playerView.setResizeMode(AspectRatioFrameLayout.RESIZE_MODE_FIT);
        playerView.setBackgroundColor(0x00000000);
        addView(playerView, new FrameLayout.LayoutParams(
            FrameLayout.LayoutParams.MATCH_PARENT,
            FrameLayout.LayoutParams.MATCH_PARENT
        ));
    }

    // ── Props set by ExoPlayerViewManager ────────────────────────────────────

    public void setFileUri(@NonNull String fileUri) {
        if (fileUri.isEmpty()) return;

        // Hard enforcement: never accept content:// URIs
        if (!fileUri.startsWith("file://")) {
            emitError("ExoPlayerView requires a file:// URI. Got a non-file URI. "
                + "Copy the file from SAF first using SafReaderModule.copyFileToCache.");
            return;
        }

        if (fileUri.equals(currentFileUri)) return;
        currentFileUri = fileUri;
        rebuildPlayer(fileUri);
    }

    public void setPaused(boolean paused) {
        this.paused = paused;
        if (player != null) {
            if (paused) {
                player.pause();
            } else {
                if (player.getPlaybackState() == Player.STATE_READY) {
                    player.play();
                } else {
                    player.setPlayWhenReady(true);
                }
            }
        }
    }

    public void setMuted(boolean muted) {
        this.muted = muted;
        if (player != null) {
            player.setVolume(muted ? 0f : 1f);
        }
    }

    // ── Internal player lifecycle ─────────────────────────────────────────────

    private void rebuildPlayer(@NonNull String fileUri) {
        releasePlayer();

        player = new ExoPlayer.Builder(getContext()).build();
        player.setRepeatMode(Player.REPEAT_MODE_ONE);
        player.setVolume(muted ? 0f : 1f);
        player.setPlayWhenReady(!paused);
        playerView.setPlayer(player);

        player.addListener(new Player.Listener() {
            @Override
            public void onPlaybackStateChanged(int state) {
                if (state == Player.STATE_READY) {
                    emitReady();
                }
            }

            @Override
            public void onPlayerError(@NonNull PlaybackException error) {
                String msg = error.getMessage();
                emitError(msg != null ? msg : "Unknown playback error");
            }

            @Override
            public void onPlayerErrorChanged(@Nullable PlaybackException error) {
                if (error != null) {
                    String msg = error.getMessage();
                    emitError(msg != null ? msg : "Unknown playback error");
                }
            }
        });

        MediaItem mediaItem = MediaItem.fromUri(Uri.parse(fileUri));
        player.setMediaItem(mediaItem);
        player.prepare();
    }

    public void releasePlayer() {
        if (player != null) {
            player.stop();
            playerView.setPlayer(null);
            player.release();
            player = null;
        }
        currentFileUri = null;
    }

    @Override
    protected void onDetachedFromWindow() {
        super.onDetachedFromWindow();
        releasePlayer();
    }

    // ── Event emission ────────────────────────────────────────────────────────

    private void emitReady() {
        try {
            WritableMap event = Arguments.createMap();
            reactContext.getJSModule(RCTEventEmitter.class)
                .receiveEvent(getId(), "onPlayerReady", event);
        } catch (Exception ignored) {}
    }

    private void emitError(String message) {
        try {
            WritableMap event = Arguments.createMap();
            event.putString("error", message != null ? message : "Playback error");
            reactContext.getJSModule(RCTEventEmitter.class)
                .receiveEvent(getId(), "onPlayerError", event);
        } catch (Exception ignored) {}
    }
}

