      onPlayerError={
        onPlayerError
          ? (e) => onPlayerError(e.nativeEvent?.error ?? 'Playback error')
          : undefined
      }
    />
  );
}

/** True when the native module is available (custom dev-client / EAS build). */
export function isAvailable(): boolean {
  return NativeExoPlayerView !== null;
}

/**
 * Expo config plugin — wires the native ExoPlayerModule into the Android build.
 *
 * During `expo prebuild` (or EAS build) this plugin:
 *   1. Copies the four Java source files into
 *      android/app/src/main/java/expo/modules/exoplayer/
 *   2. Injects Media3 Gradle dependencies into android/app/build.gradle
 *   3. Registers ExoPlayerPackage in MainApplication so React Native loads it
 */
const {
  withMainApplication,
  withDangerousMod,
  withAppBuildGradle,
} = require('@expo/config-plugins');
const path = require('path');
const fs   = require('fs');

const JAVA_SRC_DIR = path.join(
  __dirname,
  '..',
  'modules',
  'exo-player',
  'android',
  'src',
  'main',
  'java',
);

const JAVA_FILES = [
  'expo/modules/exoplayer/ExoPlayerModule.java',
  'expo/modules/exoplayer/ExoPlayerPackage.java',
  'expo/modules/exoplayer/ExoPlayerView.java',
  'expo/modules/exoplayer/ExoPlayerViewManager.java',
];

const MEDIA3_VERSION = '1.3.1';
const MEDIA3_DEPS = [
  `    implementation "androidx.media3:media3-exoplayer:${MEDIA3_VERSION}"`,
  `    implementation "androidx.media3:media3-ui:${MEDIA3_VERSION}"`,
  `    implementation "androidx.media3:media3-common:${MEDIA3_VERSION}"`,
].join('\n');

// ── Step 1: Copy Java sources ─────────────────────────────────────────────────

function withExoPlayerJavaSources(config) {
  return withDangerousMod(config, [
    'android',
    (config) => {
      const androidJavaSrcDir = path.join(
        config.modRequest.projectRoot,
        'android',
        'app',
        'src',
        'main',
        'java',
      );

      for (const relPath of JAVA_FILES) {
        const src     = path.join(JAVA_SRC_DIR, relPath);
        const dest    = path.join(androidJavaSrcDir, relPath);
        const destDir = path.dirname(dest);

        if (!fs.existsSync(destDir)) {
          fs.mkdirSync(destDir, { recursive: true });
        }

        if (fs.existsSync(src)) {
          fs.copyFileSync(src, dest);
        } else {
          console.warn(`[with-exo-player] Source file not found: ${src}`);
        }
      }

      return config;
    },
  ]);
}

// ── Step 2: Inject Media3 Gradle deps ─────────────────────────────────────────

function withExoPlayerGradleDeps(config) {
  return withAppBuildGradle(config, (config) => {
    let contents = config.modResults.contents;

    // Idempotent — skip if already present
    if (contents.includes('media3-exoplayer')) return config;

    // Insert after the opening `dependencies {` line
    contents = contents.replace(
      /^(dependencies\s*\{)/m,
      `$1\n${MEDIA3_DEPS}`,
    );

    config.modResults.contents = contents;
    return config;
  });
}

// ── Step 3: Register ExoPlayerPackage in MainApplication ──────────────────────

function withExoPlayerMainApplication(config) {
  return withMainApplication(config, (config) => {
    let contents = config.modResults.contents;

    // Idempotent — don't add twice
    if (contents.includes('ExoPlayerPackage')) return config;

    const isKotlin = config.modResults.language === 'kt';

    if (isKotlin) {
      contents = contents.replace(
        /(import com\.facebook\.react\.ReactApplication)/,
        'import expo.modules.exoplayer.ExoPlayerPackage\n$1',
      );
      contents = contents.replace(
        /(val packages = PackageList\(this\)\.packages)/,
        '$1\n      packages.add(ExoPlayerPackage())',
      );
      if (!contents.includes('ExoPlayerPackage()')) {
        contents = contents.replace(
          /(return packages)/,
          'packages.add(ExoPlayerPackage())\n      $1',
        );
      }
    } else {
      contents = contents.replace(
        /(import com\.facebook\.react\.ReactApplication;)/,
        '$1\nimport expo.modules.exoplayer.ExoPlayerPackage;',
      );
      contents = contents.replace(
        /(List<ReactPackage> packages = new PackageList\(this\)\.getPackages\(\);)/,
        '$1\n      packages.add(new ExoPlayerPackage());',
      );
      if (!contents.includes('new ExoPlayerPackage()')) {
        contents = contents.replace(
          /(return packages;)/,
          'packages.add(new ExoPlayerPackage());\n      $1',
        );
      }
    }

    config.modResults.contents = contents;
    return config;
  });
}

// ── Compose all steps ─────────────────────────────────────────────────────────

function withExoPlayer(config) {
  config = withExoPlayerJavaSources(config);
  config = withExoPlayerGradleDeps(config);
  config = withExoPlayerMainApplication(config);
  return config;
}

module.exports = withExoPlayer;

import React, { useState, useRef, useCallback, useEffect, useMemo } from 'react';
import {
  View,
  StyleSheet,
  Animated,
  Platform,
  ActivityIndicator,
  Text,
  TouchableOpacity,
} from 'react-native';
import { GestureDetector, Gesture } from 'react-native-gesture-handler';
import Reanimated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withDecay,
  runOnJS,
} from 'react-native-reanimated';
import { Image } from 'expo-image';
import { Ionicons } from '@expo/vector-icons';
import { ExoPlayerView } from '@/modules/exo-player';
import { useMedia, StatusItem, SavedItem } from '@/contexts/MediaContext';
import { useThemeColors } from '@/contexts/ThemeContext';
import { createStyles, SW, SH } from './viewerStyles';

const VIEWER_PLACEHOLDER = { blurhash: 'L6PZfSi_.AyE_3t7t7R**0o#DgR4' };

export interface ViewerItemProps {
  item: StatusItem | SavedItem;
  isActive: boolean;
  isNearActive: boolean;
  onToggleControls: () => void;
  showControls: boolean;
  controlsOpacity: Animated.Value;
}

export function ViewerItem({
  item,
  isActive,
  isNearActive,
  onToggleControls,
}: ViewerItemProps) {
  const COLORS = useThemeColors();
  const styles = useMemo(() => createStyles(COLORS), [COLORS]);
  const { prepareStatusForViewing } = useMedia();

  // displayUri is always file:// for videos — never content://
  const [displayUri, setDisplayUri] = useState<string | null>(null);
  const [isVideoReady, setIsVideoReady] = useState(false);
  const [isVideoVisible, setIsVideoVisible] = useState(false);
  const [isPreparing, setIsPreparing] = useState(false);
  const [videoError, setVideoError] = useState<string | null>(null);

  const isActiveRef = useRef(isActive);
  isActiveRef.current = isActive;

  // Cancel token for any in-flight SAF copy
  const prepareCancelRef = useRef(false);
  const revealTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hasRevealedOnceRef = useRef(false);

  // ── Raw source (may be content:// on Android 11+) ──────────────────────────
  const initialSource = useMemo(() => {
    return 'localUri' in item ? (item as SavedItem).localUri : item.uri;
  }, [item.id]); // eslint-disable-line react-hooks/exhaustive-deps

  const isSAF = initialSource.startsWith('content://');

  // ── Reveal helpers ─────────────────────────────────────────────────────────

  const clearRevealTimer = useCallback(() => {
    if (revealTimerRef.current) {
      clearTimeout(revealTimerRef.current);
      revealTimerRef.current = null;
    }
  }, []);

  const scheduleReveal = useCallback(
    (delayMs: number) => {
      clearRevealTimer();
      revealTimerRef.current = setTimeout(() => {
        hasRevealedOnceRef.current = true;
        setIsVideoVisible(true);
      }, delayMs);
    },
    [clearRevealTimer],
  );

  // ── Reset all state when item changes ──────────────────────────────────────
  useEffect(() => {
    prepareCancelRef.current = true;
    setDisplayUri(null);
    setIsVideoReady(false);
    setIsVideoVisible(false);
    setIsPreparing(false);
    setVideoError(null);
    hasRevealedOnceRef.current = false;
    clearRevealTimer();
    prepareCancelRef.current = false;
  }, [item.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Cleanup reveal timer on unmount ───────────────────────────────────────
  useEffect(() => () => clearRevealTimer(), []); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Hide video overlay when this slide becomes inactive ───────────────────
  useEffect(() => {
    if (item.type !== 'video') return;
    if (!isActive) {
      setIsVideoVisible(false);
      clearRevealTimer();
    }
  }, [isActive, item.type]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Re-schedule reveal when returning to an already-ready slide ───────────
  useEffect(() => {
    if (item.type !== 'video') return;
    if (isActive && isVideoReady && !isVideoVisible) {
      scheduleReveal(80);
    }
  }, [isActive, isVideoReady, isVideoVisible, item.type]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── CRITICAL: Prepare URI — copy SAF content:// → file:// before playback ──
  // Images: content:// is fine for expo-image (single-shot decode, no buffering).
  // Videos: MUST be a file:// URI before handing to ExoPlayer — ExoPlayer
  //   buffer-starves on SAF URIs. No content:// fallback; show error instead.
  useEffect(() => {
    if (!isNearActive) {
      // Far from viewport — release resources
      if (!isActive) {
        setDisplayUri(null);
        setIsVideoReady(false);
        setIsPreparing(false);
        setVideoError(null);
      }
      return;
    }

    if (displayUri) return; // already prepared

    if (item.type === 'image') {
      setDisplayUri(initialSource); // content:// fine for expo-image
      return;
    }

    // ── Video path ────────────────────────────────────────────────────────────
    if (!isActive) return; // only prepare the active video

    if (!isSAF) {
      // Already a file:// URI (saved gallery item) — feed directly
      setDisplayUri(initialSource);
      return;
    }

    // SAF content:// video: copy to file:// cache first — no exceptions
    setIsPreparing(true);
    setVideoError(null);
    prepareCancelRef.current = false;

    prepareStatusForViewing(item as StatusItem, { forPlayback: true })
      .then((fileUri) => {
        if (prepareCancelRef.current) return;
        setDisplayUri(fileUri);
        setIsPreparing(false);
      })
      .catch(() => {
        if (prepareCancelRef.current) return;
        // Copy failed — never fall back to content://. Show the error overlay
        // so the user can tap retry (which re-queues the copy).
        setVideoError('Could not load video — tap to retry');
        setIsPreparing(false);
      });

    return () => { prepareCancelRef.current = true; };
  }, [initialSource, isSAF, item, isNearActive, isActive, displayUri, prepareStatusForViewing]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Manual retry: clear error + displayUri to re-trigger prepare ──────────
  const handleRetry = useCallback(() => {
    setVideoError(null);
    setDisplayUri(null);
  }, []);

  // ── ExoPlayer callbacks ───────────────────────────────────────────────────

  const handlePlayerReady = useCallback(() => {
    setIsVideoReady(true);
    setVideoError(null);
    if (!hasRevealedOnceRef.current) {
      scheduleReveal(80);
    }
  }, [scheduleReveal]);

  const handlePlayerError = useCallback((error: string) => {
    setVideoError('Tap to retry');
    setIsVideoReady(false);
  }, []);

  const mediaUri = displayUri || initialSource;

  // ── Pinch-to-zoom for images ───────────────────────────────────────────────
  const imageScale = useSharedValue(1);
  const savedScale = useSharedValue(1);
  const translateX = useSharedValue(0);
  const translateY = useSharedValue(0);
  const savedTranslateX = useSharedValue(0);
  const savedTranslateY = useSharedValue(0);

  useEffect(() => {
    imageScale.value = 1;
    savedScale.value = 1;
    translateX.value = 0;
    translateY.value = 0;
    savedTranslateX.value = 0;
    savedTranslateY.value = 0;
  }, [item.id, isActive]); // eslint-disable-line react-hooks/exhaustive-deps

  const pinchGesture = Gesture.Pinch()
    .onUpdate((e) => {
      imageScale.value = Math.min(Math.max(savedScale.value * e.scale, 1), 6);
    })
    .onEnd(() => {
      if (imageScale.value < 1.15) {
        imageScale.value = withSpring(1);
        translateX.value = withSpring(0);
        translateY.value = withSpring(0);
        savedScale.value = 1;
        savedTranslateX.value = 0;
        savedTranslateY.value = 0;
      } else {
        savedScale.value = imageScale.value;
        const maxX = ((imageScale.value - 1) * SW) / 2;
        const maxY = ((imageScale.value - 1) * SW) / 2;
        if (Math.abs(translateX.value) > maxX) {
          const cx = translateX.value > 0 ? maxX : -maxX;
          translateX.value = withSpring(cx);
          savedTranslateX.value = cx;
        }
        if (Math.abs(translateY.value) > maxY) {
          const cy = translateY.value > 0 ? maxY : -maxY;
          translateY.value = withSpring(cy);
          savedTranslateY.value = cy;
        }
      }
    });

  const panGesture = Gesture.Pan()
    .manualActivation(true)
    .onTouchesMove((_e, state) => {
      if (imageScale.value > 1) state.activate();
      else state.fail();
    })
    .onUpdate((e) => {
      const scale = imageScale.value;
      const maxX = ((scale - 1) * SW) / 2;
      const maxY = ((scale - 1) * SW) / 2;
      const newX = savedTranslateX.value + e.translationX * 0.72;
      const newY = savedTranslateY.value + e.translationY * 0.72;
      translateX.value = Math.max(-maxX, Math.min(maxX, newX));
      translateY.value = Math.max(-maxY, Math.min(maxY, newY));
    })
    .onEnd((e) => {
      const scale = imageScale.value;
      const maxX = ((scale - 1) * SW) / 2;
      const maxY = ((scale - 1) * SW) / 2;
      translateX.value = withDecay(
        { velocity: e.velocityX * 0.5, deceleration: 0.92, clamp: [-maxX, maxX] },
        () => { savedTranslateX.value = translateX.value; },
      );
      translateY.value = withDecay(
        { velocity: e.velocityY * 0.5, deceleration: 0.92, clamp: [-maxY, maxY] },
        () => { savedTranslateY.value = translateY.value; },
      );
    });

  const doubleTapGesture = Gesture.Tap()
    .numberOfTaps(2)
    .maxDuration(200)
    .onEnd((e) => {
      if (imageScale.value > 1) {
        imageScale.value = withSpring(1);
        translateX.value = withSpring(0);
        translateY.value = withSpring(0);
        savedScale.value = 1;
        savedTranslateX.value = 0;
        savedTranslateY.value = 0;
      } else {
        const target = 2.5;
        imageScale.value = withSpring(target);
        savedScale.value = target;
        const maxX = ((target - 1) * SW) / 2;
        const maxY = ((target - 1) * SW) / 2;
        const tapX = Math.max(-maxX, Math.min(maxX, (SW / 2 - e.x) * (target - 1)));
        const tapY = Math.max(-maxY, Math.min(maxY, (SH / 2 - e.y) * (target - 1)));
        translateX.value = withSpring(tapX);
        translateY.value = withSpring(tapY);
        savedTranslateX.value = tapX;
        savedTranslateY.value = tapY;
      }
    });

  const singleTapGesture = Gesture.Tap()
    .numberOfTaps(1)
    .onEnd(() => { runOnJS(onToggleControls)(); });

  const imageGesture = Gesture.Simultaneous(
    pinchGesture,
    panGesture,
    Gesture.Exclusive(doubleTapGesture, singleTapGesture),
  );

  const imageAnimatedStyle = useAnimatedStyle(() => ({
    transform: [
      { scale: imageScale.value },
      { translateX: translateX.value },
      { translateY: translateY.value },
    ],
  }));

  return (
    <View style={styles.itemContainer}>
      {item.type === 'image' ? (
        <GestureDetector gesture={imageGesture}>
          <Reanimated.View style={[StyleSheet.absoluteFill, imageAnimatedStyle]}>
            <Image
              source={{ uri: mediaUri }}
              style={styles.image}
              contentFit="contain"
              cachePolicy="memory-disk"
              transition={150}
              priority={isActive ? 'high' : 'low'}
              recyclingKey={item.id}
              allowDownscaling
              decodeFormat="rgb"
              placeholder={VIEWER_PLACEHOLDER}
              placeholderContentFit="cover"
            />
          </Reanimated.View>
        </GestureDetector>
      ) : (
        <View style={StyleSheet.absoluteFill}>
          <View style={styles.videoWrap}>

            {/* ExoPlayer — only mounted when active AND we have a file:// URI.
                file:// is enforced in ExoPlayerView.java — content:// will
                emit onPlayerError immediately if it ever slips through. */}
            {isActive && displayUri && !isPreparing && (
              <ExoPlayerView
                key={`${item.id}-${displayUri}`}
                fileUri={displayUri}
                paused={false}
                muted={false}
                style={StyleSheet.absoluteFill}
                onPlayerReady={handlePlayerReady}
                onPlayerError={handlePlayerError}
              />
            )}

            {/* Thumbnail poster — shown on top until video is visible.
                For non-SAF sources videoTimestamp gives a fast frame grab;
                skip it for SAF content:// to avoid heavy IO on cheap devices. */}
            {(!isActive || !isVideoVisible) && (
              <View style={StyleSheet.absoluteFill} pointerEvents="none">
                <Image
                  source={{ uri: initialSource }}
                  style={StyleSheet.absoluteFill}
                  contentFit="contain"
                  cachePolicy="memory-disk"
                  transition={0}
                  recyclingKey={item.id}
                  {...(!isSAF ? { videoTimestamp: 500 } : {})}
                />
                {isActive && !isVideoReady && !isPreparing && !videoError && (
                  <View style={styles.videoPlayBadge} pointerEvents="none">
                    <View style={styles.videoPlayBadgeInner}>
                      <Ionicons name="play" size={28} color="#fff" />
                    </View>
                  </View>
                )}
              </View>
            )}

            {/* Spinner while copying SAF → cache */}
            {isPreparing && (
              <View style={styles.videoSpinnerWrap} pointerEvents="none">
                <ActivityIndicator color="#fff" size="large" />
                <Text style={{ color: '#fff', marginTop: 12, fontSize: 12 }}>
                  Loading video…
                </Text>
              </View>
            )}

            {/* Retry overlay on playback error or copy failure */}
            {videoError && !isPreparing && (
              <TouchableOpacity
                style={[
                  StyleSheet.absoluteFill,
                  {
                    justifyContent: 'center',
                    alignItems: 'center',
                    backgroundColor: 'rgba(0,0,0,0.65)',
                  },
                ]}
                onPress={handleRetry}
                activeOpacity={0.8}
              >
                <Ionicons name="refresh-circle-outline" size={52} color="#fff" />
                <Text style={{ color: '#fff', marginTop: 10, fontSize: 14 }}>
                  Tap to retry
                </Text>
              </TouchableOpacity>
            )}
          </View>
        </View>
      )}
    </View>
  );
}

