   142→  // wipe the cache directory under storage pressure between sessions.
   143→  const existing = memMap[item.id];
   144→  if (existing) {
   145→    try {
   146→      const info = await FileSystem.getInfoAsync(existing);
   147→      if (info.exists && (info as any).size > 0) {
   148→        return; // still good — nothing to do
   149→      }
   150→    } catch {
   151→      // fall through and regenerate
   152→    }
   153→    delete memMap[item.id];
   154→  }
   155→
   156→  if (item.type === 'image') {
   157→    // For images we don't keep a separate file — expo-image's own disk
   158→    // cache is already a fast file-system lookup keyed by URI hash. We
   159→    // just warm it with a single prefetch call and from then on every
   160→    // grid render is a memory/disk hit, not a content:// round-trip.
   161→    if (imagesPrefetched.has(item.uri)) return;
   162→    imagesPrefetched.add(item.uri);
   163→    try {
   164→      await ExpoImage.prefetch(item.uri, 'memory-disk');
   165→    } catch {
   166→      // prefetch failure is harmless — Glide will still try on first paint
   167→    }
   168→    return;
