   175→  //   MediaMetadataRetriever entirely in Java — no JS bridge overhead, no
   176→  //   second process hop. It writes atomically via .tmp+rename itself.
   177→  //
   178→  // JS FALLBACK (Expo Go / no native module):
   179→  //   expo-video-thumbnails — also hardware-accelerated but crosses the
   180→  //   JS bridge twice (request + result) and writes to a temp dir that
   181→  //   we then have to move into our managed cache dir.
   182→  const dir = await ensureCacheDir();
   183→  if (!dir) return;
   184→  const dest = `${dir}vid_${safeFilename(item.id)}.jpg`;
   185→
   186→  try {
   187→    if (SafReaderModule.isAvailable()) {
   188→      // Native Java path — fastest, no bridge overhead for data transfer.
   189→      // The source URI may be a content:// SAF URI or a file:// local path;
   190→      // Java handles both via setDataSource(context, uri) vs setDataSource(path).
   191→      await SafReaderModule.generateThumbnail(item.uri, dest, 0);
   192→    } else {
