   194→      const tmp = `${dest}.tmp`;
   195→      const result = await VideoThumbnails.getThumbnailAsync(item.uri, {
   196→        time: 0,
   197→        quality: 0.5,
   198→      });
   199→      try { await FileSystem.deleteAsync(tmp, { idempotent: true }); } catch {}
   200→      await FileSystem.copyAsync({ from: result.uri, to: tmp });
   201→      try { await FileSystem.deleteAsync(dest, { idempotent: true }); } catch {}
   202→      await FileSystem.moveAsync({ from: tmp, to: dest });
   203→      try { await FileSystem.deleteAsync(result.uri, { idempotent: true }); } catch {}
   204→    }
   205→    memMap[item.id] = dest;
   206→    schedulePersist();
   207→    notify(item.id, dest);
   208→  } catch {
