   230→    await init();
   231→    while (queue.length > 0 && cancelToken === myToken) {
   232→      const next = queue.shift();
   233→      if (!next) break;
   234→      await generateOne(next);
   235→      // Idle gap between items. ~80 ms keeps the JS thread fully available
   236→      // for touch / scroll handlers — the user's input always wins over
   237→      // background thumbnail work.
   238→      await new Promise((r) => setTimeout(r, 150));
   239→    }
   240→  } finally {
   241→    processing = false;
   242→  }
   243→}
