    10→import { ThumbnailCache } from '@/lib/thumbnail-cache';
    11→
    12→export function useThumbnail(id: string): string | null {
    13→  const [path, setPath] = useState<string | null>(() => ThumbnailCache.get(id));
    14→  useEffect(() => {
    15→    // Re-read on mount in case the cache populated between render and effect
    16→    const current = ThumbnailCache.get(id);
    17→    if (current !== path) setPath(current);
    18→    const unsub = ThumbnailCache.subscribe(id, setPath);
    19→    return unsub;
    20→    // eslint-disable-next-line react-hooks/exhaustive-deps
    21→  }, [id]);
    22→  return path;
    23→}
